node --input-type=module - <<'NODE'
import pLimit from './index.js';
import {setTimeout as delay} from 'node:timers/promises';
const limit = pLimit({concurrency: 1});
const running = limit(() => delay(25));
const pending = limit(() => 'should stay pending by default');
await Promise.resolve();
limit.clearQueue();
console.log(await Promise.race([
  pending.then(value => ({state: 'fulfilled', value}), error => ({state: 'rejected', name: error?.name, message: error?.message})),
  delay(50).then(() => ({state: 'still-pending'}))
]));
await running;
NODE

node --input-type=module - <<'NODE'
import pLimit from './index.js';
let threw = false;
try {
  pLimit({concurrency: 1, rejectOnClear: 0});
} catch {
  threw = true;
}
console.log({threw});
NODE
Expected: threw should be true because rejectOnClear is not boolean. Actual: {threw:false}.

node --input-type=module - <<'NODE'
import pLimit from './index.js';
const limit = pLimit(1);
console.log(await limit.map(new Set(['a', 'b']), (_value, index) => index));
NODE
Expected: [0, 1]. Actual: [undefined, undefined] (serialized as [null, null] by JSON.stringify).

